// ErrEscape is returned when rel resolves to a location outside base.
var ErrEscape = errors.New("safepath: path escapes base")

// Resolve returns the absolute, lexically cleaned path for rel within base.
// The base itself is a valid result (for rel "" or "."). Paths that escape
// base, including sibling-prefix traversals such as "/a/foo" vs "/a/foobar",
// are rejected with ErrEscape. Symbolic links are not resolved.
func Resolve(base, rel string) (string, error) {
	if strings.ContainsRune(rel, 0) {
		return "", errors.New("safepath: invalid NUL byte in path")
	}

	absBase, err := filepath.Abs(base)
	if err != nil {
		return "", err
	}
	absBase = filepath.Clean(absBase)

	var target string
	if filepath.IsAbs(rel) {
		// An absolute rel is only acceptable if it already lies within base.
		target = filepath.Clean(rel)
	} else {
		target = filepath.Join(absBase, rel)
	}

	// Build the prefix that any strict descendant must start with.
	// For the filesystem root, base already ends with a separator.
	prefix := absBase
	if !strings.HasSuffix(prefix, string(os.PathSeparator)) {
		prefix += string(os.PathSeparator)
	}

	if target == absBase || strings.HasPrefix(target, prefix) {
		return target, nil
	}
	return "", ErrEscape
